<?php
require_once __DIR__.'/../includes/bootstrap.php';
require_login();
$id=(int)($_GET['id']??0);
$album=['title'=>'','artist'=>'','description'=>'','cover_file'=>null];
if($id){$s=$pdo->prepare('SELECT * FROM albums WHERE id=?');$s->execute([$id]);$album=$s->fetch()?:$album;}
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'save_album')==='save_album'){
    verify_csrf();
    try{
        $cover=$album['cover_file'];
        if(!empty($_FILES['cover']['name'])){$cover=upload_file($_FILES['cover'],dirname(__DIR__).'/uploads/covers',['image/jpeg','image/png','image/webp'],10*1024*1024);}
        if($id){$s=$pdo->prepare('UPDATE albums SET title=?,artist=?,description=?,cover_file=? WHERE id=?');$s->execute([trim($_POST['title']),trim($_POST['artist']),trim($_POST['description']),$cover,$id]);}
        else{$s=$pdo->prepare('INSERT INTO albums(title,artist,description,cover_file) VALUES(?,?,?,?)');$s->execute([trim($_POST['title']),trim($_POST['artist']),trim($_POST['description']),$cover]);$id=(int)$pdo->lastInsertId();}
        flash('success','Albumdaten gespeichert. Jetzt können die Titel hochgeladen werden.');
        redirect('admin/album_edit.php?id='.$id);
    }catch(Throwable $e){flash('danger',$e->getMessage());redirect('admin/album_edit.php'.($id?'?id='.$id:''));}
}
if($_SERVER['REQUEST_METHOD']==='POST' && in_array(($_POST['action']??''),['create_share','update_share','delete_share'],true)){
    verify_csrf();$action=$_POST['action'];
    if($action==='create_share'){
        $token=random_token(24);$expires=trim($_POST['expires_at']??'')?:null;$hash=trim($_POST['password']??'')!==''?password_hash($_POST['password'],PASSWORD_DEFAULT):null;
        $s=$pdo->prepare('INSERT INTO shares(album_id,token,label,password_hash,expires_at,allow_download) VALUES(?,?,?,?,?,?)');
        $s->execute([$id,$token,trim($_POST['label']??''),$hash,$expires,!empty($_POST['allow_download'])?1:0]);flash('success','Freigabelink erstellt.');
    }elseif($action==='update_share'){
        $shareId=(int)($_POST['share_id']??0);$expires=trim($_POST['expires_at']??'')?:null;
        if(trim($_POST['password']??'')!==''){$s=$pdo->prepare('UPDATE shares SET label=?,password_hash=?,expires_at=?,allow_download=? WHERE id=? AND album_id=?');$s->execute([trim($_POST['label']??''),password_hash($_POST['password'],PASSWORD_DEFAULT),$expires,!empty($_POST['allow_download'])?1:0,$shareId,$id]);}
        else{$s=$pdo->prepare('UPDATE shares SET label=?,expires_at=?,allow_download=? WHERE id=? AND album_id=?');$s->execute([trim($_POST['label']??''),$expires,!empty($_POST['allow_download'])?1:0,$shareId,$id]);}
        flash('success','Freigabelink aktualisiert.');
    }else{$s=$pdo->prepare('DELETE FROM shares WHERE id=? AND album_id=?');$s->execute([(int)($_POST['share_id']??0),$id]);flash('success','Freigabelink gelöscht.');}
    redirect('admin/album_edit.php?id='.$id.'#freigaben');
}
$tracks=[];$shares=[];
if($id){$s=$pdo->prepare('SELECT * FROM tracks WHERE album_id=? ORDER BY disc_no,track_no,id');$s->execute([$id]);$tracks=$s->fetchAll();$s=$pdo->prepare('SELECT * FROM shares WHERE album_id=? ORDER BY created_at DESC');$s->execute([$id]);$shares=$s->fetchAll();}
render_header($id?'Album verwalten':'Neues Album',true);
?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2 mb-1"><?=$id?'Album verwalten':'Neues Album'?></h1><p class="text-body-secondary mb-0"><?=$id?'Metadaten, Titel und Freigaben an einem Ort.':'Zuerst Albumdaten und Cover anlegen.'?></p></div><a class="btn btn-outline-secondary" href="index.php">Zurück</a></div>
<form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="save_album"><div class="row g-4"><div class="col-lg-8"><div class="card shadow-sm"><div class="card-body"><div class="row g-3"><div class="col-md-7"><label class="form-label">Albumtitel</label><input class="form-control" name="title" value="<?=e($album['title'])?>" required></div><div class="col-md-5"><label class="form-label">Interpret</label><input class="form-control" name="artist" value="<?=e($album['artist'])?>"></div><div class="col-12"><label class="form-label">Beschreibung</label><textarea class="form-control" name="description" rows="4"><?=e($album['description'])?></textarea></div></div></div></div></div><div class="col-lg-4"><div class="card shadow-sm"><div class="card-body"><label class="form-label">Cover</label><?php if($album['cover_file']):?><img class="album-cover mb-3" src="<?=base_url('uploads/covers/'.$album['cover_file'])?>" alt=""><?php endif?><input class="form-control" type="file" name="cover" accept="image/jpeg,image/png,image/webp"><button class="btn btn-primary w-100 mt-3"><?=$id?'Albumdaten speichern':'Album erstellen'?></button></div></div></div></div></form>
<?php if($id):?>
<div class="card shadow-sm mt-4" id="upload"><div class="card-header d-flex justify-content-between align-items-center"><div><span class="fw-semibold">Titel hochladen</span><span class="badge text-bg-secondary ms-2"><?=count($tracks)?></span></div><button class="btn btn-sm btn-primary" type="button" data-bs-toggle="collapse" data-bs-target="#trackUploadPanel" aria-expanded="false" aria-controls="trackUploadPanel">Neue Titel hochladen</button></div><div id="trackUploadPanel" class="collapse"><div class="card-body">
<div id="uploadDropzone" class="upload-dropzone text-center p-4"><div class="fs-1">⇧</div><h2 class="h5">Audiodateien hier ablegen</h2><p class="text-body-secondary mb-3">Dateien werden vor dem Upload mit Name, Größe und erkannten MP3-Tags angezeigt.</p><input id="trackFiles" type="file" accept="audio/*,.flac" multiple hidden><button type="button" class="btn btn-primary" id="chooseTracks">Dateien auswählen</button></div>
<div id="uploadQueue" class="vstack gap-2 mt-4"></div></div></div></div>
<div class="card shadow-sm mt-4" id="reihenfolge"><div class="card-header d-flex justify-content-between align-items-center"><span class="fw-semibold">CDs und Reihenfolge</span><button id="addDisc" class="btn btn-sm btn-outline-primary" type="button">CD hinzufügen</button></div><div class="card-body"><p class="text-body-secondary">Titel per Drag-and-drop innerhalb einer CD oder auf eine andere CD verschieben. Die Titelnummer entsteht automatisch aus der Position.</p><div id="discBoards" class="vstack gap-4" data-album="<?=$id?>" data-csrf="<?=csrf_token()?>"><?php $grouped=[];foreach($tracks as $t){$grouped[max(1,(int)$t['disc_no'])][]=$t;}if(!$grouped)$grouped=[1=>[]];foreach($grouped as $disc=>$discTracks):?><section class="disc-board border rounded-3 p-3" data-disc="<?=$disc?>"><div class="d-flex justify-content-between align-items-center mb-3"><h3 class="h6 mb-0">CD <span class="disc-number"><?=$disc?></span></h3><?php if($disc>1):?><button class="btn btn-sm btn-outline-danger remove-disc" type="button">CD entfernen</button><?php endif?></div><div class="disc-track-list vstack gap-2 min-disc-height"><?php foreach($discTracks as $t):?><div class="track-admin-row border rounded-3 p-3 bg-body" draggable="true" data-id="<?=$t['id']?>"><div class="d-flex align-items-center gap-3"><div class="drag-handle" title="Verschieben">☰</div><div class="track-auto-no badge text-bg-secondary"></div><input class="form-control form-control-sm track-title" value="<?=e($t['title'])?>"><button class="btn btn-sm btn-outline-danger track-delete" type="button">Löschen</button></div></div><?php endforeach?></div></section><?php endforeach?></div><div class="d-flex justify-content-end mt-3"><button id="saveTrackOrder" class="btn btn-primary" type="button">Reihenfolge speichern</button></div></div></div>
<div class="card shadow-sm mt-4" id="freigaben"><div class="card-header fw-semibold">Freigabelinks</div><div class="card-body"><div class="row g-4"><div class="col-lg-5"><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="create_share"><div class="mb-3"><label class="form-label">Bezeichnung</label><input class="form-control" name="label" placeholder="z. B. Kunde / Veranstaltung"></div><div class="mb-3"><label class="form-label">Optionales Passwort</label><input type="password" class="form-control" name="password"></div><div class="mb-3"><label class="form-label">Ablaufdatum</label><input type="datetime-local" class="form-control" name="expires_at"></div><div class="form-check mb-3"><input class="form-check-input" type="checkbox" name="allow_download" id="allowDownload" checked><label class="form-check-label" for="allowDownload">Downloads erlauben</label></div><button class="btn btn-primary">Freigabelink erstellen</button></form></div><div class="col-lg-7"><div class="vstack gap-3"><?php foreach($shares as $sh):$url=base_url('share.php?token='.$sh['token']);?><div class="border rounded-3 p-3"><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="update_share"><input type="hidden" name="share_id" value="<?=$sh['id']?>"><div class="row g-2"><div class="col-md-7"><label class="form-label small">Bezeichnung</label><input class="form-control form-control-sm" name="label" value="<?=e($sh['label'])?>"></div><div class="col-md-5"><label class="form-label small">Ablaufdatum</label><input type="datetime-local" class="form-control form-control-sm" name="expires_at" value="<?=e($sh['expires_at']?date('Y-m-d\TH:i',strtotime($sh['expires_at'])):'')?>"></div><div class="col-md-7"><label class="form-label small">Neues Passwort</label><input type="password" class="form-control form-control-sm" name="password" placeholder="Leer lassen zum Beibehalten"></div><div class="col-md-5 d-flex align-items-end"><div class="form-check mb-2"><input class="form-check-input" type="checkbox" name="allow_download" id="dl<?=$sh['id']?>" <?=$sh['allow_download']?'checked':''?>><label class="form-check-label" for="dl<?=$sh['id']?>">Downloads erlauben</label></div></div></div><div class="small share-url text-break my-3"><?=e($url)?></div><div class="d-flex flex-wrap gap-2"><button class="btn btn-sm btn-primary">Änderungen speichern</button><button type="button" class="btn btn-sm btn-outline-primary" onclick="navigator.clipboard.writeText('<?=e($url)?>')">Link kopieren</button><a class="btn btn-sm btn-outline-secondary" target="_blank" href="<?=e($url)?>">Öffnen</a></div></form><form method="post" class="mt-2" onsubmit="return confirm('Freigabelink wirklich löschen?')"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="delete_share"><input type="hidden" name="share_id" value="<?=$sh['id']?>"><button class="btn btn-sm btn-outline-danger">Freigabelink löschen</button></form></div><?php endforeach?><?php if(!$shares):?><div class="text-body-secondary">Noch keine Freigaben vorhanden.</div><?php endif?></div></div></div></div></div>
<script>window.albumUploadConfig={uploadUrl:<?=json_encode(base_url('admin/track_upload.php'))?>,updateUrl:<?=json_encode(base_url('admin/track_update.php'))?>,deleteUrl:<?=json_encode(base_url('admin/track_delete.php'))?>,albumId:<?=$id?>,csrf:<?=json_encode(csrf_token())?>};</script>
